int count = 0;
double x, y;
std::mt19937 gen(seed);
std::uniform_real_distribution<double> dis_x(a, b);
std::uniform_real_distribution<double> dis_y(0.0, fmax);
for (int i = 0; i < n_points; i++) {
    x = dis_x(gen);
    y = dis_y(gen);
    if (y <= f(x)) {
        count++;
    }
}
return (b - a) * fmax * static_cast<double>(count) / n_points;

